-- Test fixture for the privilege-escalation and database-function checks.

create type public.app_role as enum ('user', 'moderator', 'admin');

-- user_roles: users may add rows for themselves, so they can pick 'admin'.
create table public.user_roles (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id),
  role public.app_role not null
);
alter table public.user_roles enable row level security;
create policy "Read own roles" on public.user_roles for select using (auth.uid() = user_id);
create policy "Add own roles" on public.user_roles for insert with check (auth.uid() = user_id);

-- The helper lives in a private schema, as Supabase suggests, and a policy trusts it.
create schema private;
create function private.is_moderator()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.user_roles where user_id = auth.uid() and role in ('moderator', 'admin'));
$$;
create policy "Moderators read all roles" on public.user_roles for select using (private.is_moderator());

-- accounts: three privilege columns, each protected a different way. All safe.
create table public.accounts (
  id uuid primary key references auth.users(id),
  display_name text,
  plan text not null default 'free' check (plan in ('free', 'pro')),
  credits int not null default 0,
  is_admin boolean not null default false
);
alter table public.accounts enable row level security;
create policy "Read own account" on public.accounts for select using (auth.uid() = id);
-- credits: WITH CHECK pins it to the current value.
create policy "Update own account" on public.accounts for update
  using (auth.uid() = id)
  with check (auth.uid() = id and credits = (select a.credits from public.accounts a where a.id = auth.uid()));
-- is_admin: not in the column grants.
revoke update on public.accounts from anon, authenticated;
grant update (display_name, plan, credits) on public.accounts to authenticated;
-- plan: a trigger puts it back.
create function public.keep_plan() returns trigger language plpgsql as $$
begin
  if new.plan is distinct from old.plan then
    new.plan := old.plan;
  end if;
  return new;
end;
$$;
create trigger keep_plan before update on public.accounts for each row execute function public.keep_plan();

-- members: a home-made login table with passwords in it.
create table public.members (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references auth.users(id),
  email text not null,
  password text not null
);
alter table public.members enable row level security;

-- exec_sql: runs whatever SQL it is given, with the owner's rights.
create function public.exec_sql(query text) returns void
language plpgsql security definer set search_path = public as $$
begin
  execute query;
end;
$$;

-- get_email: anyone can look up any user's email.
create function public.get_email(uid uuid) returns text
language sql stable security definer set search_path = public as $$
  select email from auth.users where id = uid;
$$;

-- my_roles: security definer, but only returns the caller's rows. Safe.
create function public.my_roles() returns setof public.user_roles
language sql stable security definer set search_path = public as $$
  select * from public.user_roles where user_id = auth.uid();
$$;

-- touch: harmless, but security definer without a search_path.
create function public.touch() returns void
language plpgsql security definer as $$
begin
  perform 1;
end;
$$;

-- find_members: security invoker, but pastes its argument into SQL.
create function public.find_members(pattern text) returns setof public.members
language plpgsql as $$
begin
  return query execute format('select * from public.members where email like ''%s''', pattern);
end;
$$;

-- count_by_email: dynamic SQL done right, with USING. Safe.
create function public.count_by_email(address text) returns bigint
language plpgsql security definer set search_path = public as $$
declare n bigint;
begin
  execute 'select count(*) from public.members where email = $1' into n using address;
  return n;
end;
$$;

-- internal_cleanup: deletes rows, but the API roles can't call it. Safe.
create function public.internal_cleanup() returns void
language plpgsql security definer set search_path = public as $$
begin
  delete from public.members where email = '';
end;
$$;
revoke execute on function public.internal_cleanup() from public, anon, authenticated;

-- feedback: an identity id like tables made in the Supabase dashboard, and
-- anyone may send feedback (a classic spam target).
create table public.feedback (
  id bigint generated by default as identity primary key,
  message text not null
);
alter table public.feedback enable row level security;
create policy "Anyone can send feedback" on public.feedback for insert with check (true);
